%[text] # 3D Acoustic Imaging Example
%[text] This example combines the toolbox functions for 3D in-air acoustic imaging: generating the directions to image, simulating a sensor measurement, beamforming with DMAS-CF, and viewing the result as a directional map, as a 3D point cloud and isosurfaces, and as a 2D horizontal slice.
%[text] ## Setup scene and sensor
%[text] Seven point reflectors at different directions and ranges in front of a 32 microphone array, three of them in the horizontal plane. Directions use the right-handed coordinate system of the toolbox: X forward, Y to the left and Z up, so positive azimuth is to the left and positive elevation is up.
structScene = struct();
structScene.targetAzimuth   = [0    -35    30    45   -20    10   -45];
structScene.targetElevation = [0     20     0    30   -35    40     0];
structScene.targetRange     = [1.5   2.0   1.8   2.6   2.3   3.0   2.8];
structScene.targetStrength  = [1     1     1     0.7   1     0.7   1];
structScene.speedOfSound = 343;

structSensor = struct();
structSensor.sampleRate = 450e3;
structSensor.emissionSignal = clait.fm_sweep(80e3, 20e3, structSensor.sampleRate, 2, 1, 10);
structSensor.coordinatesEmitter = [0 0 0.05];
structSensor.numSamplesSensor = 15000;
structSensor.coordinatesMicrophones = [0 -0.0384 0.0151; 0 -0.0232 0.0101; 0 -0.0121 0.0164; 0 -0.0046 0.0153; ...
                                       0 -0.0367 0.0054; 0 -0.0144 0.0061; 0 0.0054 0.0011; 0 0.0273 -0.0027; ...
                                       0 -0.0387 0.0001; 0 -0.0281 0.0002; 0 -0.0094 -0.0013; 0 -0.0060 -0.0000; ...
                                       0 -0.0357 -0.0117; 0 -0.0318 -0.0112; 0 -0.0286 -0.0166; 0 0.0029 -0.0086; ...
                                       0 -0.0011 0.0178; 0 0.0067 0.0115; 0 0.0103 0.0144; 0 0.0172 0.0140; ...
                                       0 0.0384 0.0022; 0 0.0283 0.0162; 0 0.0354 0.0125; 0 0.0373 0.0150; ...
                                       0 -0.0084 -0.0047; 0 0.0107 -0.0111; 0 0.0189 -0.0166; 0 0.0363 -0.0101; ...
                                       0 0.0057 -0.0224; 0 -0.0036 -0.0223; 0 0.0315 -0.0161; 0 0.0083 -0.0178];
%%
%[text] ## Generate the directions to image
%[text] For 3D imaging the directions have to cover azimuth and elevation. A regular azimuth/elevation grid wastes directions near the poles, so here `clait.generateDirections` spreads them nearly uniformly with equal-area partitioning, 2 degrees apart, within a 70 degree cone around the sensor axis. Run `help clait.generateDirections` for the other patterns.
directionOptions = clait.generateDirections('options');
directionOptions.spacing = 2;
directionOptions.coneAngle = 70;
[directionsAzimuth, directionsElevation] = clait.generateDirections('equalarea', directionOptions);
fprintf('%d directions\n', numel(directionsAzimuth)); %[output:8764c1fe]
%%
%[text] ## Setup imaging
structImage = struct();
structImage.directionsAzimuth = directionsAzimuth;
structImage.directionsElevation = directionsElevation;
structImage.numDirections = numel(directionsAzimuth);
structImage.lowpassFreq = 5e3;
structImage.doEnvelope = 1;
structImage.doThresholdAtZero = 1;
structImage.decimationFactor = 10;
structImage.matchedFilterMethod = 'Normal';
structImage.matchedFilterFreq = [20e3 80e3];
structImage.doMatchedFilter = 1;
structImage.methodImaging = 'DMAS3';
structImage.coherenceType = 'CF';
structImage.methodProcessing = 'mexcuda';   % Falls back to the CPU if no NVIDIA GPU is available
%%
%[text] ## Simulate a measurement and calculate the 3D acoustic image
dataMicrophones = clait.simulateMicrophoneData(structScene, structSensor);
dataMicrophones = dataMicrophones + 0.02 * randn(size(dataMicrophones));

tic;
image3D = clait.calculateAcousticImage(dataMicrophones, structSensor, structImage);
fprintf('3D image of %d range bins x %d directions in %.2f s\n', size(image3D, 1), size(image3D, 2), toc); %[output:5bb88f00]
%%
%[text] ## Directional overview
%[text] `clait.plotSphericalEnergyscape` shows the peak over range for every direction on a Lambert equal-area projection of the sphere. The black circles mark the true target directions.
figure('Position', [100 100 650 520]); %[output:3ae5ed87]
opts = clait.plotSphericalEnergyscape('options');
opts.labelStyle = 'graticule';
opts.dbCut = -40;
opts.title = 'DMAS3-CF, peak over range';
clait.plotSphericalEnergyscape(image3D, structSensor, structImage, opts); %[output:3ae5ed87]

% True target directions on the same Lambert projection (positive azimuth on the left)
k = sqrt(2 ./ (1 + cosd(structScene.targetElevation) .* cosd(structScene.targetAzimuth))) / sqrt(2);
hold on; %[output:3ae5ed87]
plot(-k .* cosd(structScene.targetElevation) .* sind(structScene.targetAzimuth), ... %[output:3ae5ed87]
     k .* sind(structScene.targetElevation), 'ko', 'MarkerSize', 14, 'LineWidth', 1.5); %[output:3ae5ed87]
hold off; %[output:3ae5ed87]
%%
%[text] ## 3D point cloud
%[text] `clait.plot3DEnergyscape` places every range bin of every direction in 3D space. Everything within 30 dB of the peak is shown, louder points larger and more opaque. The red circles mark the true target positions. Rotate the figure to look around.
[targetX, targetY, targetZ] = sph2cart(deg2rad(structScene.targetAzimuth), deg2rad(structScene.targetElevation), structScene.targetRange);

figure('Position', [100 100 800 650]); %[output:5c720285]
opts = clait.plot3DEnergyscape('options');
opts.dbCut = -30;
opts.title = 'DMAS3-CF point cloud, 30 dB';
clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:5c720285]
hold on; %[output:5c720285]
plot3(targetX, targetY, targetZ, 'ro', 'MarkerSize', 12, 'LineWidth', 1.5); %[output:5c720285]
hold off; %[output:5c720285]
%%
%[text] ## 3D isosurfaces
%[text] The same image as nested surfaces at -6, -12 and -20 dB.
figure('Position', [100 100 800 650]); %[output:29b4ffb2]
opts = clait.plot3DEnergyscape('options');
opts.renderMode = 'isosurface';
opts.isoLevels = [-6 -12 -20];
opts.title = 'DMAS3-CF isosurfaces at -6, -12 and -20 dB';
clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:29b4ffb2]
%%
%[text] ## DAS versus DMAS3-CF in 3D
%[text] With the same 30 dB window, conventional DAS shows the sidelobes of every reflector as a cloud around it, while DMAS3-CF keeps the reflectors compact.
structImageDAS = structImage;
structImageDAS.methodImaging = 'DAS';
structImageDAS.coherenceType = 'none';
imageDAS = clait.calculateAcousticImage(dataMicrophones, structSensor, structImageDAS);

figure('Position', [100 100 1300 550]); %[output:3e520f56]
layout = tiledlayout(1, 2, 'TileSpacing', 'compact'); %[output:3e520f56]
opts = clait.plot3DEnergyscape('options');
opts.dbCut = -30;
opts.showColorbar = false;

nexttile; %[output:3e520f56]
opts.title = 'DAS';
clait.plot3DEnergyscape(imageDAS, structSensor, structImageDAS, opts); %[output:3e520f56]

nexttile; %[output:3e520f56]
opts.title = 'DMAS3-CF';
opts.showColorbar = true;
[~, hCbar] = clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:3e520f56]
hCbar.Layout.Tile = 'east'; %[output:3e520f56]
%%
%[text] ## 2D horizontal slice
%[text] For a quick 2D view, `clait.generateDirections` can also make a horizontal fan of directions at zero elevation, which `clait.plotPolarEnergyscape` shows as a range/azimuth image. Only the three reflectors in the horizontal plane appear. The image is cropped to 3.5 m, as every image row is one decimated sample of the round-trip time.
structImage2D = structImage;
[structImage2D.directionsAzimuth, structImage2D.directionsElevation] = ...
    clait.generateDirections('2d', struct('spacing', 1, 'azimuthLimits', [-90 90]));
structImage2D.numDirections = numel(structImage2D.directionsAzimuth);
image2D = clait.calculateAcousticImage(dataMicrophones, structSensor, structImage2D);
rangeVector = (0:size(image2D, 1) - 1) * structImage2D.decimationFactor / structSensor.sampleRate * structScene.speedOfSound / 2;
image2D = image2D(rangeVector <= 3.5, :);

figure('Position', [100 100 800 500]); %[output:8e7a76c2]
opts = clait.plotPolarEnergyscape('options');
opts.useSimplePlot = true;
opts.dbCut = -40;
opts.title = 'DMAS3-CF, elevation 0';
clait.plotPolarEnergyscape(image2D, structSensor, structImage2D, opts); %[output:8e7a76c2]

